-- =====================================================================
-- SIGAF · Fase 3b · 049 · Saldos de dictamen por unidad (FINAT IMKK036 "Rep. Disponibilidad Dictamen")
-- Fecha: 29/10/2026
-- Qué hace:
--   · Crea dictamenes (encabezado: origen, fecha, corte, totales) y dictamen_saldos (DETALLE DE SALDOS:
--     una fila por unidad de información · centro · cuenta · periodo, con importe definitivo, pagos y disponible).
--   · Carga 39 dictámenes (980 renglones) de los PDF IMKK036 corridos el 21 y 29/10/2026.
--     Cada dictamen se validó: la suma de sus renglones cuadra al centavo con el renglón TOTALES del PDF.
--   · Corrige el número de dictamen de 3 contratos con el que trae el SAI (SALDO DE LOS CONTRATOS 29/10):
--       S6M0010  0000094357-2026 → 0000211470-2026
--       S6M0046  0000094360-2026 → 0000211466-2026
--       050GYR032N08426-149-00 (D6M0107)  0000322059-2026 → 0000467664-2026 (DEF)
-- Unidad 010102 = HGZ 2. Las demás unidades se guardan para saber si otra unidad tiene saldo (oficio de apoyo).
-- Permisos: leer = cualquier usuario con sesión; escribir = personal de Finanzas (fn_es_personal).
-- Se puede correr dos veces: borra y vuelve a cargar los mismos dictámenes.
-- Cómo: SQL Editor de Supabase → Run. Al final muestra cada contrato con su dictamen y lo del HGZ 2.
-- =====================================================================
create table if not exists dictamenes (
  numero            text primary key,
  origen            text,            -- DEF / PRE
  fecha_dictamen    date,
  corte             date,            -- fecha de ejecución del IMKK036
  archivo           text,
  total_definitivo  numeric(14,2),
  total_pagos       numeric(14,2),
  total_disponible  numeric(14,2),
  actualizado_at    timestamptz not null default now()
);

create table if not exists dictamen_saldos (
  dictamen          text not null references dictamenes(numero) on delete cascade,
  ui                text not null,   -- unidad de información (010102 = HGZ 2)
  centro            text not null,
  cuenta            text not null,
  anio              int  not null,
  mes               int  not null,
  previo            numeric(14,2),
  ajuste_previo     numeric(14,2),
  ajuste_post       numeric(14,2),
  definitivo        numeric(14,2),
  pagos             numeric(14,2),   -- en positivo
  cant_pagos        int,
  disponible        numeric(14,2),
  disponible_acum   numeric(14,2),
  primary key (dictamen, ui, centro, cuenta, anio, mes)
);
create index if not exists idx_dictamen_saldos_ui on dictamen_saldos (ui);

alter table dictamenes      enable row level security;
alter table dictamen_saldos enable row level security;
drop policy if exists dic_read on dictamenes;
create policy dic_read on dictamenes for select using (auth.role() = 'authenticated');
drop policy if exists dic_write on dictamenes;
create policy dic_write on dictamenes for all using (public.fn_es_personal()) with check (public.fn_es_personal());
drop policy if exists dsa_read on dictamen_saldos;
create policy dsa_read on dictamen_saldos for select using (auth.role() = 'authenticated');
drop policy if exists dsa_write on dictamen_saldos;
create policy dsa_write on dictamen_saldos for all using (public.fn_es_personal()) with check (public.fn_es_personal());

-- Carga (borra y vuelve a cargar los dictámenes de este lote)
delete from dictamenes where numero in ('0000007125-2025', '0000031654-2025', '0000041413-2025', '0000047286-2025', '0000056673-2026', '0000059287-2026', '0000076588-2026', '0000088391-2026', '0000094209-2026', '0000097084-2026', '0000097085-2026', '0000100779-2026', '0000104077-2026', '0000115659-2026', '0000115663-2026', '0000115672-2026', '0000115681-2026', '0000118610-2026', '0000123587-2026', '0000137420-2026', '0000137439-2026', '0000137441-2026', '0000137442-2026', '0000137444-2026', '0000152504-2026', '0000155456-2026', '0000155458-2026', '0000175543-2026', '0000205281-2026', '0000211466-2026', '0000211470-2026', '0000233878-2026', '0000271322-2026', '0000271331-2026', '0000271336-2026', '0000277104-2026', '0000277107-2026', '0000277112-2026', '0000467664-2026');



-- Números de dictamen corregidos con el SAI
update contratos set dictamen_numero = '0000211470-2026' where upper(numero_interno) = 'S6M0010' and dictamen_numero = '0000094357-2026';
update contratos set dictamen_numero = '0000211466-2026' where upper(numero_interno) = 'S6M0046' and dictamen_numero = '0000094360-2026';
update contratos set dictamen_numero = '0000467664-2026', dictamen_tipo = 'DEF'
 where dictamen_numero = '0000322059-2026'
   and (upper(numero_interno) in ('050GYR032N08426-149-00', 'D6M0107') or upper(coalesce(numero_alterno, '')) in ('050GYR032N08426-149-00', 'D6M0107'));

-- Verificación: contratos con dictamen y lo que el IMKK036 dice del HGZ 2
select c.numero_interno, c.dictamen_numero, d.corte,
       sum(s.definitivo) filter (where s.ui = '010102') as asignado_hgz2,
       sum(s.pagos)      filter (where s.ui = '010102') as pagado_hgz2,
       sum(s.disponible) filter (where s.ui = '010102') as disponible_hgz2,
       sum(s.disponible) filter (where s.ui <> '010102') as disponible_otras_unidades
from contratos c
left join dictamenes d on d.numero = c.dictamen_numero
left join dictamen_saldos s on s.dictamen = c.dictamen_numero
where c.dictamen_numero ~ '^[0-9]{10}-[0-9]{4}$'
group by c.numero_interno, c.dictamen_numero, d.corte
order by (d.corte is null) desc, c.numero_interno;
